H.background();
// Absolute value equation:  |x - h| = d   (distance from h equals d)
// Solutions are the two points h - d and h + d on the number line.
const h = P.h, d = Math.abs(P.d);
H.text("Absolute value equation:  |x − h| = d", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
const nSols = d > 1e-9 ? 2 : (Math.abs(d) <= 1e-9 ? 1 : 0);
H.text("|x − " + h.toFixed(1) + "| = " + d.toFixed(1) + "   means: x is distance " + d.toFixed(1) + " from " + h.toFixed(1), 24, 52, { color: H.colors.sub, size: 13 });
const W = H.W, Ht = H.H;
const v = H.plot2d({ xMin: -10, xMax: 10, yMin: -2, yMax: 2, box: { x: 50, y: Ht * 0.5, w: W - 100, h: 90 } });
v.line(-10, 0, 10, 0, { color: H.colors.axis, width: 2 });
for (let i = -10; i <= 10; i++) {
  v.line(i, -0.22, i, 0.22, { color: H.colors.grid, width: 1 });
  if (i % 2 === 0) v.text(String(i), i, -0.95, { color: H.colors.sub, size: 11, align: "center" });
}
// center h
v.dot(h, 0, { r: 5, fill: H.colors.violet });
v.text("h = " + h.toFixed(1), h, 1.5, { color: H.colors.violet, size: 12, align: "center" });
const x1 = h - d, x2 = h + d;
// distance brackets from h out to each solution
v.line(h, 0.55, x1, 0.55, { color: H.colors.accent, width: 3 });
v.line(h, -0.55, x2, -0.55, { color: H.colors.accent2, width: 3 });
v.text("dist " + d.toFixed(1), (h + x1) / 2, 1.05, { color: H.colors.accent, size: 11, align: "center" });
v.text("dist " + d.toFixed(1), (h + x2) / 2, -1.25, { color: H.colors.accent2, size: 11, align: "center" });
// solution dots
v.dot(x1, 0, { r: 7, fill: H.colors.good });
v.dot(x2, 0, { r: 7, fill: H.colors.good });
v.text("x = " + x1.toFixed(1), x1, 1.5, { color: H.colors.good, size: 12, align: "center" });
v.text("x = " + x2.toFixed(1), x2, 1.5, { color: H.colors.good, size: 12, align: "center" });
// animated probe: a dot sweeping the line; its bar grows = |x - h|, glows when it equals d
const xp = h + (d + 3) * Math.sin(t * 0.8);
const dist = Math.abs(xp - h);
const hit = Math.abs(dist - d) < 0.12;
v.dot(xp, 0, { r: hit ? 8 + Math.sin(t * 8) : 5, fill: hit ? H.colors.warn : H.colors.accent });
H.text("|x − h| sweeps:  current |x − " + h.toFixed(1) + "| = " + dist.toFixed(2) + (hit ? "  = d  ✓ solution!" : ""), 24, Ht * 0.5 - 22, { color: hit ? H.colors.warn : H.colors.sub, size: 13 });
H.text(nSols === 2 ? "two solutions" : nSols === 1 ? "one solution (x = h)" : "no solution (d < 0)", 24, Ht * 0.5 + 90, { color: H.colors.good, size: 13, weight: 700 });

H.background();
// Absolute value inequality:  |x - h| < d  (or > d, toggle with `gt`).
// Graph y = |x - h| and the line y = d; the solution is where the V is below
// (or above) the line. "less than" -> the BETWEEN band; "greater" -> OUTSIDE.
const h = P.h, d = Math.abs(P.d), gt = P.gt >= 0.5;
const v = H.plot2d({ xMin: -10, xMax: 10, yMin: -1, yMax: 9 });
v.grid(); v.axes();
const x1 = h - d, x2 = h + d;
// draw solution band on the axis (y just above 0)
if (!gt) {
  v.line(x1, 0.18, x2, 0.18, { color: H.colors.good, width: 8 });
} else {
  v.line(-10, 0.18, x1, 0.18, { color: H.colors.good, width: 8 });
  v.line(x2, 0.18, 10, 0.18, { color: H.colors.good, width: 8 });
}
// the V and the threshold line
v.line(-10, d, 10, d, { color: H.colors.violet, width: 2, dash: [6, 6] });
v.fn(x => Math.abs(x - h), { color: H.colors.accent, width: 3 });
v.dot(h, 0, { r: 6, fill: H.colors.accent2 });
// boundary points where V crosses the line
v.dot(x1, d, { r: 6, fill: H.colors.warn });
v.dot(x2, d, { r: 6, fill: H.colors.warn });
v.text("x = " + x1.toFixed(1), x1, d + 0.7, { color: H.colors.warn, size: 11, align: "center" });
v.text("x = " + x2.toFixed(1), x2, d + 0.7, { color: H.colors.warn, size: 11, align: "center" });
// animated probe walking the V; turns green inside the solution set
const xp = h + (d + 4) * Math.sin(t * 0.7);
const yp = Math.abs(xp - h);
const inSol = gt ? (yp > d) : (yp < d);
v.dot(xp, yp, { r: 6 + (inSol ? Math.sin(t * 5) : 0), fill: inSol ? H.colors.good : H.colors.sub });
v.line(xp, 0, xp, yp, { color: inSol ? H.colors.good : H.colors.sub, width: 1.5, dash: [3, 3] });
H.text("Absolute value inequality:  |x − h| " + (gt ? ">" : "<") + " d", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
const setText = gt ? ("x < " + x1.toFixed(1) + "  or  x > " + x2.toFixed(1) + "   (outside)")
                   : (x1.toFixed(1) + " < x < " + x2.toFixed(1) + "   (between)");
H.text("h = " + h.toFixed(1) + "   d = " + d.toFixed(1) + "   →   " + setText, 24, 52, { color: H.colors.sub, size: 13 });
H.text("probe x = " + xp.toFixed(2) + ":  |x − h| = " + yp.toFixed(2) + (inSol ? "  ✓ in solution" : "  ✗ not"), 24, 76, { color: inSol ? H.colors.good : H.colors.sub, size: 13 });
H.legend([{ label: "y = |x − h|", color: H.colors.accent }, { label: "y = d", color: H.colors.violet }, { label: "solution set", color: H.colors.good }], H.W - 190, 100);

H.background();
const w = H.W, hh = H.H;
const a = Math.round(P.a), b = Math.round(P.b), c = Math.round(P.c), d = Math.round(P.d);
// Combine like terms in  a x + c + b x + d  ->  (a+b) x + (c+d)
const xc = a + b, kc = c + d;
H.text("Combine like terms:  ax + c + bx + d", 24, 32, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Only matching kinds add: x-tiles join x-tiles, units join units.", 24, 54, { color: H.colors.sub, size: 13 });
// original expression with x-terms in accent, constants in accent2
H.text(a + "x", 60, 96, { color: H.colors.accent, size: 22, weight: 700 });
H.text("+ " + c, 110, 96, { color: H.colors.accent2, size: 22, weight: 700 });
H.text("+ " + b + "x", 168, 96, { color: H.colors.accent, size: 22, weight: 700 });
H.text("+ " + d, 234, 96, { color: H.colors.accent2, size: 22, weight: 700 });
// tile model: each x-tile a tall bar, each unit a small square. animate a gather.
const gather = (Math.sin(t * 0.8) + 1) / 2; // 0..1 pulse: spread <-> grouped
const baseY = 250, tileW = 26, gap = 6;
// x tiles (a then b) slide together
let xi = 0;
const total = a + b;
for (let i = 0; i < total; i++) {
  const spreadX = 70 + i * (tileW + gap) + (i >= a ? 60 : 0); // gap between the two groups when spread
  const groupX = 70 + i * (tileW + gap);
  const tx = H.lerp(spreadX, groupX, gather);
  H.rect(tx, baseY - 70, tileW, 70, { fill: H.colors.accent, stroke: H.colors.bg, width: 1, radius: 3 });
  xi = tx + tileW;
}
H.text("x-tiles", 70, baseY + 18, { color: H.colors.accent, size: 13 });
H.text("count = " + xc, 70, baseY + 36, { color: H.colors.sub, size: 12 });
// unit tiles on the right
const ux0 = w * 0.6;
const totalU = c + d;
for (let i = 0; i < totalU; i++) {
  const spreadX = ux0 + i * (tileW + gap) + (i >= c ? 50 : 0);
  const groupX = ux0 + i * (tileW + gap);
  const tx = H.lerp(spreadX, groupX, gather);
  H.rect(tx, baseY - 26, tileW, 26, { fill: H.colors.accent2, stroke: H.colors.bg, width: 1, radius: 3 });
}
H.text("unit tiles", ux0, baseY + 18, { color: H.colors.accent2, size: 13 });
H.text("count = " + kc, ux0, baseY + 36, { color: H.colors.sub, size: 12 });
// result
H.rect(50, baseY + 60, w - 100, 56, { fill: "#13243f", stroke: H.colors.accent, width: 2, radius: 10 });
H.text("= " + xc + "x + " + kc, 70, baseY + 96, { color: H.colors.good, size: 24, weight: 700 });
H.text("(" + a + "+" + b + ")x = " + xc + "x ,  (" + c + "+" + d + ") = " + kc, 24, hh - 22, { color: H.colors.sub, size: 13 });

H.background();
const v = H.plot2d({ xMin: -10, xMax: 10, yMin: -3, yMax: 3 });
v.grid({ stepY: 100 }); v.axes({ stepY: 100 });
let lo = P.lo, hi = P.hi;
if (lo > hi) { const tmp = lo; lo = hi; hi = tmp; }
const isAnd = P.mode < 0.5;
if (isAnd) {
  v.line(lo, 0, hi, 0, { color: H.colors.good, width: 6 });
} else {
  v.line(-10, 0, lo, 0, { color: H.colors.good, width: 6 });
  v.line(hi, 0, 10, 0, { color: H.colors.good, width: 6 });
}
v.circle(lo, 0, 8, { stroke: H.colors.warn, width: 3, fill: H.colors.bg });
v.circle(hi, 0, 8, { stroke: H.colors.warn, width: 3, fill: H.colors.bg });
v.text("lo", lo - 0.2, -0.9, { color: H.colors.warn, size: 12 });
v.text("hi", hi - 0.2, -0.9, { color: H.colors.warn, size: 12 });
const xs = 9 * Math.sin(t * 0.6);
const inBand = xs > lo && xs < hi;
const ok = isAnd ? inBand : !inBand;
v.dot(xs, 0, { r: 7, fill: ok ? H.colors.good : H.colors.sub });
H.text("Compound: " + (isAnd ? "lo < x < hi   (AND / between)" : "x < lo  OR  x > hi   (outside)"), 24, 30, { color: H.colors.ink, size: 16, weight: 700 });
H.text("lo = " + lo.toFixed(1) + "   hi = " + hi.toFixed(1) + "   test x = " + xs.toFixed(2) + "  ->  " + (ok ? "in the solution" : "not a solution"), 24, 52, { color: H.colors.sub, size: 12 });

H.background();
const w = H.W, h = H.H;
const count = Math.max(2, Math.round(P.count));
const step = Math.max(1, Math.round(P.gap));
const first = Math.round(P.first);
const y0 = h * 0.56;
const xL = 70, xR = w - 60;
H.line(xL, y0, xR, y0, { color: H.colors.axis, width: 2 });
const lo = first - 1, hi = first + step * (count - 1) + 1;
const sx = (n) => xL + (n - lo) / Math.max(1e-6, (hi - lo)) * (xR - xL);
for (let n = lo; n <= hi; n++) {
  H.line(sx(n), y0 - 5, sx(n), y0 + 5, { color: H.colors.grid, width: 1 });
  H.text(String(n), sx(n), y0 + 22, { color: H.colors.sub, size: 11, align: "center" });
}
let sum = 0;
const active = Math.floor((t * 1.2) % (count + 1));
for (let i = 0; i < count; i++) {
  const n = first + step * i;
  sum += n;
  const on = i <= active;
  H.circle(sx(n), y0, on ? 11 : 8, { fill: on ? H.colors.accent : H.colors.panel, stroke: H.colors.accent2, width: 2 });
  H.text(i === 0 ? "n" : "n+" + (step * i), sx(n), y0 - 24, { color: on ? H.colors.ink : H.colors.sub, size: 13, align: "center" });
  if (i < count - 1) {
    const mx = (sx(n) + sx(n + step)) / 2;
    H.text("+" + step, mx, y0 - 8, { color: H.colors.good, size: 11, align: "center" });
  }
}
H.text("Consecutive integers: n, n+" + step + ", n+" + (2 * step) + ", ...   (" + count + " terms)", 24, 30, { color: H.colors.ink, size: 16, weight: 700 });
H.text("first n = " + first + "    gap = " + step + "    count = " + count + "    ->  sum = " + sum, 24, 52, { color: H.colors.sub, size: 13 });
H.text("Sum = " + count + "n + " + (step * count * (count - 1) / 2) + "  =  " + count + "(" + first + ") + " + (step * count * (count - 1) / 2) + "  =  " + sum, 24, h - 26, { color: H.colors.good, size: 13 });

H.background();
// Coordinate plane basics: an ordered pair (a, b). Walk RIGHT a along x, then
// UP b along y to reach the point. Show which quadrant it lands in.
const a = P.a, b = P.b;
const v = H.plot2d({ xMin: -8, xMax: 8, yMin: -8, yMax: 8 });
v.grid(); v.axes();
// quadrant labels
v.text("Q1", 6.5, 6.5, { color: H.colors.sub, size: 12, align: "center" });
v.text("Q2", -6.5, 6.5, { color: H.colors.sub, size: 12, align: "center" });
v.text("Q3", -6.5, -6.5, { color: H.colors.sub, size: 12, align: "center" });
v.text("Q4", 6.5, -6.5, { color: H.colors.sub, size: 12, align: "center" });
// animate the "walk": phase 0->1 moves along x, 1->2 moves up along y, then loops
const ph = (t % 4) / 2; // 0..2 over 4s
const fx = H.clamp(ph, 0, 1);
const fy = H.clamp(ph - 1, 0, 1);
const wx = a * fx;
const wy = b * fy;
// x-run leg (origin to (wx,0))
v.arrow(0, 0, wx, 0, { color: H.colors.accent, width: 3 });
// y-run leg (from (a,0) up to (a, wy))
if (fx >= 0.999) v.arrow(a, 0, a, wy, { color: H.colors.good, width: 3 });
// dashed guide to the final point
v.line(a, 0, a, b, { color: H.colors.grid, width: 1.5, dash: [4, 4] });
v.line(0, b, a, b, { color: H.colors.grid, width: 1.5, dash: [4, 4] });
// moving traveler dot
v.dot(fx < 1 ? wx : a, fx < 1 ? 0 : wy, { r: 6, fill: H.colors.warn });
// final point marker (pulsing)
v.dot(a, b, { r: 6 + Math.sin(t * 3), fill: H.colors.accent2 });
v.text("(" + a.toFixed(1) + ", " + b.toFixed(1) + ")", a, b + 0.8, { color: H.colors.accent2, size: 13, align: "center" });
const quad = (a > 0 && b > 0) ? "Quadrant I" : (a < 0 && b > 0) ? "Quadrant II"
           : (a < 0 && b < 0) ? "Quadrant III" : (a > 0 && b < 0) ? "Quadrant IV"
           : (a === 0 && b === 0) ? "the origin" : "on an axis";
H.text("Coordinate plane:  the point (a, b)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("a = " + a.toFixed(1) + " (right/left)   b = " + b.toFixed(1) + " (up/down)   →   " + quad, 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "x-run  a", color: H.colors.accent }, { label: "y-rise  b", color: H.colors.good }], H.W - 160, 100);

H.background();
const v = H.plot2d({ xMin: 0, xMax: 10, yMin: 0, yMax: 8 });
v.grid(); v.axes();
const a = P.a, b = P.b, c = P.c;
// Area model: a rectangle of width a and height (b + c), split into two pieces.
const widthA = Math.max(0.2, Math.abs(a));
const hB = Math.max(0, b), hC = Math.max(0, c);
// pulse a sweeping highlight across the two sub-rectangles
const phase = (t * 0.5) % 2;
const lit1 = phase < 1, lit2 = !lit1;
v.rect(0.5, 0.5, widthA, hB, { fill: lit1 ? H.colors.accent : H.colors.panel, stroke: H.colors.ink, width: 2 });
v.rect(0.5, 0.5 + hB, widthA, hC, { fill: lit2 ? H.colors.accent2 : H.colors.panel, stroke: H.colors.ink, width: 2 });
v.text("a·b = " + (a * b).toFixed(1), 0.5 + widthA / 2, 0.5 + hB / 2, { color: H.colors.ink, size: 14, align: "center", baseline: "middle" });
v.text("a·c = " + (a * c).toFixed(1), 0.5 + widthA / 2, 0.5 + hB + hC / 2, { color: H.colors.ink, size: 14, align: "center", baseline: "middle" });
v.line(0.5, 0.5, 0.5, 0.5 + hB + hC, { color: H.colors.good, width: 2 });
v.text("height b+c = " + (b + c).toFixed(1), 0.5 + widthA + 0.2, 0.5 + (hB + hC) / 2, { color: H.colors.good, size: 12, align: "left", baseline: "middle" });
H.text("Distributive property:  a(b + c) = ab + ac", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("a=" + a.toFixed(1) + "  b=" + b.toFixed(1) + "  c=" + c.toFixed(1) + "   →  " + a.toFixed(1) + "·" + (b + c).toFixed(1) + " = " + (a * b).toFixed(1) + " + " + (a * c).toFixed(1) + " = " + (a * (b + c)).toFixed(1), 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "a·b", color: H.colors.accent }, { label: "a·c", color: H.colors.accent2 }], H.W - 150, 28);

H.background();
const v = H.plot2d({ xMin: -8, xMax: 8, yMin: -8, yMax: 8 });
v.grid(); v.axes();
const lo = Math.min(P.xlo, P.xhi), hi = Math.max(P.xlo, P.xhi);
const amp = P.amp;
const f = x => amp * Math.sin(x);
const pts = [];
const N = 80;
let yMinR = Infinity, yMaxR = -Infinity;
for (let i = 0; i <= N; i++) { const x = lo + (hi - lo) * i / N; const y = f(x); pts.push([x, y]); if (y < yMinR) yMinR = y; if (y > yMaxR) yMaxR = y; }
v.path(pts, { color: H.colors.accent, width: 3 });
v.line(lo, -8, lo, 8, { color: H.colors.good, width: 1.5, dash: [4, 4] });
v.line(hi, -8, hi, 8, { color: H.colors.good, width: 1.5, dash: [4, 4] });
v.line(lo, 0, hi, 0, { color: H.colors.good, width: 4 });
v.line(0, yMinR, 0, yMaxR, { color: H.colors.violet, width: 4 });
v.dot(lo, f(lo), { r: 5, fill: H.colors.accent });
v.dot(hi, f(hi), { r: 5, fill: H.colors.accent });
const frac = (Math.sin(t * 0.6) + 1) / 2;
const xs = lo + (hi - lo) * frac;
v.dot(xs, f(xs), { r: 7, fill: H.colors.warn });
v.dot(xs, 0, { r: 4, fill: H.colors.good });
v.dot(0, f(xs), { r: 4, fill: H.colors.violet });
H.text("Domain & range from a graph", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("domain x in [" + lo.toFixed(1) + ", " + hi.toFixed(1) + "]    range y in [" + yMinR.toFixed(1) + ", " + yMaxR.toFixed(1) + "]", 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "domain (x-values)", color: H.colors.good }, { label: "range (y-values)", color: H.colors.violet }], H.W - 200, 28);

H.background();
const p = (Math.abs(Math.round(P.p)) < 1) ? 1 : Math.round(P.p), q = (Math.abs(Math.round(P.q)) < 1) ? 1 : Math.round(P.q);
const r = P.r;
const step = Math.max(0, Math.min(2, Math.round(P.step)));
function gcd(m, n){ m = Math.abs(m); n = Math.abs(n); while(n){ const tmp = n; n = m % n; m = tmp; } return m || 1; }
const L = Math.abs(p * q) / gcd(p, q);
const x = (r - 1 / q) * p;            // solve  x/p + 1/q = r
const v = H.plot2d({ xMin: -1, xMax: 11, yMin: -1, yMax: 5 });
v.grid({ stepY: 1 }); v.axes({ ticks: false });
const breathe = 0.85 + 0.15 * Math.sin(t * 1.6);
// LHS and RHS drawn as equal-length bars: a balanced scale. Multiplying by L
// scales BOTH equally, so they stay balanced — but now the numbers are whole.
const lhs = step === 0 ? (x / p + 1 / q) : (L * x / p + L / q);
const rhs = step === 0 ? r : (L * r);
const yL = 3, yR = 1.3;
v.rect(0, yL, Math.max(0.02, lhs) * breathe, 0.7, { fill: H.colors.accent + "55", stroke: H.colors.accent, width: 2 });
v.rect(0, yR, Math.max(0.02, rhs) * breathe, 0.7, { fill: H.colors.good + "55", stroke: H.colors.good, width: 2 });
v.text("LHS = " + lhs.toFixed(2), 0.2, yL + 0.35, { color: H.colors.ink, size: 13 });
v.text("RHS = " + rhs.toFixed(2), 0.2, yR + 0.35, { color: H.colors.ink, size: 13 });
H.text("Clear fractions:  x/p + 1/q = r", 24, 30, { color: H.colors.ink, size: 17, weight: 700 });
const msg = step === 0 ? ("LCD L = " + L + ".  Both bars equal → balanced.") : step === 1 ? ("×L on BOTH sides keeps balance: (L/p)·x + L/q = L·r") : ("now whole numbers → x = " + x.toFixed(2));
H.text("p=" + p + "  q=" + q + "  r=" + r.toFixed(1) + "  L=" + L + "   step " + step + "/2   " + msg, 24, 52, { color: H.colors.sub, size: 12 });
if (step >= 2) { v.dot(0, -0.4, { r: 6 + Math.sin(t * 3), fill: H.colors.good }); v.text("x = " + x.toFixed(2), 0.3, -0.4, { color: H.colors.good, size: 14 }); }
// a "×L" badge slides between the two bars to show the same multiplier hits both
const sy = H.map(0.5 + 0.5 * Math.sin(t * 1.5), 0, 1, v.Y(yR + 0.35), v.Y(yL + 0.35));
const bx = v.X(Math.max(lhs, rhs) * breathe) + 28;
H.circle(bx, sy, 14, { fill: H.colors.violet });
H.text("×L", bx - 10, sy + 4, { color: H.colors.bg, size: 12, weight: 700 });

H.background();
const a = (Math.abs(P.a) < 1e-9) ? 1 : P.a, b = P.b, c = P.c;
const step = Math.max(0, Math.min(2, Math.round(P.step)));
const x = c / a - b;            // from a(x+b)=c  -> x = c/a - b
const v = H.plot2d({ xMin: -1, xMax: 10, yMin: -1, yMax: 6 });
v.grid({ stepX: 1, stepY: 1 }); v.axes({ ticks: false });
// AREA MODEL: a rectangle of height |a|, split into width x and width b.
// Area = a*(x+b) = a*x + a*b = the distributed form.
