if (Math.abs(A) < 1e-6 && Math.abs(C) < 1e-6) { kind = "degenerate (no x², y²)"; col = H.colors.sub; }
else if (Math.abs(A) < 1e-6 || Math.abs(C) < 1e-6) { kind = "Parallel lines (one square missing)"; col = H.colors.good; }
else if (A * C < 0) { kind = "Hyperbola"; col = H.colors.warn; }
else if (Math.abs(A - C) < 1e-6) { kind = "Circle"; col = H.colors.yellow; }
else { kind = "Ellipse"; col = H.colors.accent; }
// Solve A·x² + C·y² = 4 honestly for each case.
if (Math.abs(C) > 1e-6 && Math.abs(A) > 1e-6) {
  // both squared terms present: ellipse / circle / hyperbola — y = ±√((k - A x²)/C)
  const pts = [], pts2 = [];
  for (let i = 0; i <= 240; i++) {
    const x = -8 + (16 * i) / 240;
    const rhs = (k - A * x * x) / C;
    if (rhs >= 0) pts.push([x, Math.sqrt(rhs)]);
  }
  for (let i = 240; i >= 0; i--) {
    const x = -8 + (16 * i) / 240;
    const rhs = (k - A * x * x) / C;
    if (rhs >= 0) pts2.push([x, -Math.sqrt(rhs)]);
  }
  if (pts.length) v.path(pts, { color: col, width: 3 });
  if (pts2.length) v.path(pts2, { color: col, width: 3 });
